namespace VampPon.UnitySpike.Editor {public static class U48ProductionVisualIosSimulatorBuild {public static void Build(){var output=Path.GetFullPath(Path.Combine(UnityEngine.Application.dataPath,"../Builds/iOS-U48-Production-Verification"));var property=typeof(PlayerSettings.iOS).GetProperty("simulatorSdkArchitecture",BindingFlags.Public|BindingFlags.Static);var sdk=PlayerSettings.iOS.sdkVersion;var arch=property?.GetValue(null);try{PlayerSettings.iOS.sdkVersion=iOSSdkVersion.SimulatorSDK;var arm=Enum.GetNames(property.PropertyType).First(v=>v.Contains("ARM64",StringComparison.OrdinalIgnoreCase));property.SetValue(null,Enum.Parse(property.PropertyType,arm));Directory.CreateDirectory(output);var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/_Project/Scenes/Boot/Boot.unity","Assets/_Project/Scenes/Stage1/Stage1.unity"},locationPathName=output,target=BuildTarget.iOS,options=BuildOptions.None,extraScriptingDefines=new[]{"VAMPPON_AI_SIMULATOR_SMOKE"}});if(report.summary.result!=BuildResult.Succeeded)throw new InvalidOperationException($"U48 production export failed: {report.summary.result}");}finally{PlayerSettings.iOS.sdkVersion=sdk;if(property!=null&&arch!=null)property.SetValue(null,arch);AssetDatabase.SaveAssets();}}}}
